using AfriWallet.Compliance.Readiness.Checks;using AfriWallet.Compliance.Readiness.Models;using AfriWallet.Compliance.Readiness.Services;
var root=Directory.GetCurrentDirectory();while(!Directory.Exists(Path.Combine(root,"backend"))&&Directory.GetParent(root) is { } parent)root=parent.FullName;
IComplianceReadinessCheck[] checks=[new DeliveryPresenceCheck(),new ArchitectureBoundaryCheck(),new SandboxBoundaryCheck(),new SecretBoundaryCheck(),new RegulatoryClaimCheck(),new AuditCapabilityCheck()];var report=await new ComplianceReadinessRunner(checks).RunAsync(root);foreach(var check in report.Checks){var status=check.Status switch{ReadinessStatus.Passed=>"PASS",ReadinessStatus.Failed=>"FAIL",_=>"SKIP"};Console.WriteLine($"{check.Code,-12} {check.Name,-42} {status}");Console.WriteLine($"             Evidence: {check.Evidence}");}Console.WriteLine($"\nChecks:  {report.Total}\nPassed:  {report.Passed}\nFailed:  {report.Failed}\nSkipped: {report.Skipped}\n");if(!report.IsReady){Console.WriteLine("Decision: NOT READY");Environment.ExitCode=1;return;}Console.WriteLine("Compliance readiness scenarios PASS");Console.WriteLine("Production compliance provider certification: NOT CLAIMED");Console.WriteLine("Regulatory approval: NOT CLAIMED");Console.WriteLine("Decision: READY FOR COMPLIANCE RC");